                    .shadow(color: shadow.color, radius: shadow.blur / 2, x: shadow.x, y: shadow.y)
            } else {
                shape.fill(look.background ?? .clear)
            }
            if let shadow = look.shadow, shadow.inset {
                shape
                    .fill(
                        Color.white.shadow(
                            .inner(
                                color: shadow.color, radius: shadow.blur / 2, x: shadow.x,
                                y: shadow.y))
                    )
                    .blendMode(.multiply)
            }
        }
    }
